-- Bronze: land orders_*.csv EXACTLY as received. No cleaning. No dedupe.
{{ config(materialized='incremental', unique_key=none, partition_by='_ingest_date') }}

with raw as (
    select * from {{ source('vendor', 'orders_landing') }}
),

stamped as (
    select
        raw.*,                                    -- every source column, untouched
        'vendor.orders'          as _source,       -- lineage: where it came from
        current_timestamp        as _loaded_at,    -- lineage: when we landed it
        _dbt_source_file         as _source_file,  -- lineage: which file
        date(current_timestamp)  as _ingest_date   -- partition key
    from raw
)

select * from stamped
{% if is_incremental() %}
  where _ingest_date > (select max(_ingest_date) from {{ this }})  -- append-only
{% endif %}

