# Source contract for the `purchase` event (v2) — the door bad events cannot walk through.
CONTRACT = {
    "version": "purchase.v2",
    "required": {
        "event_id": str,        # idempotency key — dedupes at-least-once delivery
        "user_id": str,
        "purchase_cents": int,  # the field the SDK renamed -> this is the trap
        "currency": str,
        "event_ts": float,      # client epoch seconds
    },
    "freshness_sla_secs": 3600,  # an event older than 1h vs now is STALE
}

def check(event: dict, now: float) -> tuple[str, str]:
    for field, typ in CONTRACT["required"].items():
        if field not in event:
            return ("quarantine", f"schema_violation: missing {field}")
        if not isinstance(event[field], typ):
            return ("quarantine", f"type_violation: {field} is {type(event[field]).__name__}")
    if now - event["event_ts"] > CONTRACT["freshness_sla_secs"]:
        return ("quarantine", "freshness_violation: event older than SLA")
    return ("pass", "ok")  # only now may it enter raw landing + lineage

