-- source contract SLA: orders must be < 2h stale, partitioned by _hour
{{ config(materialized='incremental', unique_key='order_id',
          incremental_strategy='insert_overwrite', partition_by={'field':'order_date','data_type':'date'}) }}

with fresh_orders as (
  select * from {{ source('ops','orders') }}
  {% if is_incremental() %}
    -- BUDGET: prune to the lookback window, never full-scan
    where _hour >= (select max(_hour) from {{ this }}) - interval '3' hour
  {% endif %}
),
guarded as (
  -- FRESHNESS GATE: quarantine rows older than the SLA instead of trusting them
  select *, case when _hour < now() - interval '2' hour then 'STALE' else 'OK' end as _gate
  from fresh_orders
)
select order_date, sum(amount) as revenue, count(*) as order_count
from guarded where _gate = 'OK'
group by order_date

